pub(crate) fn account_label_is_pii(label: &AccountAlias) -> bool {
    let raw = label.label.as_ref();
    if raw.is_empty() {
        return false;
    }
    let mut digits = 0usize;
    for (idx, ch) in raw.chars().enumerate() {
        if idx == 0 && ch == '+' {
            continue;
        }
        if ch.is_ascii_digit() {
            digits += 1;
            continue;
        }
        if matches!(ch, '-' | '.') {
            continue;
        }
        return false;
    }
    matches!(digits, 8..=15)
}
