struct StatelessValidationCacheEntry {
    order: u64,
    expires_at_ms: Option<u128>,
    not_before_ms: u128,
}
#[derive(Debug, Clone, Copy)]
struct StatelessValidationCacheWarmEntry {
    signed_hash: HashOf<SignedTransaction>,
    expires_at_ms: Option<u128>,
    not_before_ms: u128,
}
fn stateless_validation_cache_warm_entry(
    tx: &crate::tx::AcceptedTransaction<'_>,
    max_clock_drift_ms: u128,
) -> Option<StatelessValidationCacheWarmEntry> {
    let prepared = tx.stateless_cache_metadata()?;
    prepared.single_ed25519_key?;
    let expires_at_ms = tx
        .time_to_live()
        .and_then(|ttl| tx.creation_time().checked_add(ttl))
        .map(|expires_at| expires_at.as_millis());
    let not_before_ms = tx
        .creation_time()
        .as_millis()
        .saturating_sub(max_clock_drift_ms);
    Some(StatelessValidationCacheWarmEntry {
        signed_hash: prepared.signed_hash,
        expires_at_ms,
        not_before_ms,
    })
}
#[derive(Debug)]
pub(crate) struct StatelessValidationCache {
    cap: usize,
    next_order: u64,
    context: Option<StatelessValidationContext>,
    entries: std::collections::HashMap<
        iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
        StatelessValidationCacheEntry,
    >,
    lru: std::collections::BTreeSet<(
        u64,
        iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
    )>,
}
impl StatelessValidationCache {
    fn new(cap: usize) -> Self {
        Self {
            cap,
            next_order: 0,
            context: None,
            entries: std::collections::HashMap::new(),
            lru: std::collections::BTreeSet::new(),
        }
    }
    pub(crate) fn set_cap(&mut self, cap: usize) {
        self.cap = cap;
        if self.cap == 0 {
            self.entries.clear();
            self.lru.clear();
            self.next_order = 0;
            return;
        }
        self.evict_capacity();
    }
    pub(crate) fn ensure_context(&mut self, context: StatelessValidationContext) {
        if self.context.as_ref() != Some(&context) {
            self.context = Some(context);
            self.entries.clear();
            self.lru.clear();
            self.next_order = 0;
        }
    }
    pub(crate) fn get_ok(
        &self,
        key: &iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
        now_ms: u128,
    ) -> bool {
        self.entries.get(key).is_some_and(|entry| {
            now_ms >= entry.not_before_ms
                && entry
                    .expires_at_ms
                    .is_none_or(|expires_at| now_ms < expires_at)
        })
    }
    #[cfg(test)]
    pub(crate) fn contains_key(
        &self,
        key: &iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
    ) -> bool {
        self.entries.contains_key(key)
    }
    pub(crate) fn insert_ok(
        &mut self,
        key: iroha_crypto::HashOf<iroha_data_model::transaction::SignedTransaction>,
        expires_at_ms: Option<u128>,
        not_before_ms: u128,
    ) {
        if self.cap == 0 {
            return;
        }
        if let Some(entry) = self.entries.remove(&key) {
            self.lru.remove(&(entry.order, key.clone()));
        }
        self.evict_capacity();
        let order = self.next_order();
        self.entries.insert(
            key.clone(),
            StatelessValidationCacheEntry {
                order,
                expires_at_ms,
                not_before_ms,
            },
        );
        self.lru.insert((order, key));
    }
    fn next_order(&mut self) -> u64 {
        let order = self.next_order;
        self.next_order = self.next_order.wrapping_add(1);
        order
    }
    fn evict_capacity(&mut self) {
        if self.cap == 0 {
            self.entries.clear();
            self.lru.clear();
            return;
        }
        while self.entries.len() >= self.cap {
            let Some((order, key)) = self.lru.pop_first() else {
                self.entries.clear();
                break;
            };
            self.entries.remove(&key);
            self.lru.remove(&(order, key));
        }
    }
}
#[cfg(test)]
mod stateless_validation_cache_tests {
    use super::{StatelessValidationCache, StatelessValidationContext};
    use iroha_crypto::{Algorithm, Hash, HashOf};
    use iroha_data_model::{
        NetworkId, block::BlockHeader, parameter::TransactionParameters,
        transaction::SignedTransaction,
    };
    fn dummy_hash(seed: u8) -> HashOf<SignedTransaction> {
        HashOf::from_untyped_unchecked(Hash::new([seed]))
    }
    #[test]
    fn cache_tracks_inserted_hashes_and_capacity() {
        let mut cache = StatelessValidationCache::new(1);
        let key = dummy_hash(7);
        let other_key = dummy_hash(8);
        cache.insert_ok(key, Some(200), 50);
        assert!(!cache.get_ok(&key, 49));
        assert!(cache.get_ok(&key, 100));
        assert!(!cache.get_ok(&key, 200));
        cache.insert_ok(other_key, None, 0);
        assert!(!cache.get_ok(&key, 100));
        assert!(cache.get_ok(&other_key, 100));
    }
    #[test]
    fn cache_refresh_updates_lru_order() {
        let mut cache = StatelessValidationCache::new(2);
        let first = dummy_hash(1);
        let second = dummy_hash(2);
        let third = dummy_hash(3);
        cache.insert_ok(first, None, 0);
        cache.insert_ok(second, None, 0);
        cache.insert_ok(first, None, 0);
        cache.insert_ok(third, None, 0);
        assert!(cache.get_ok(&first, 100));
        assert!(!cache.get_ok(&second, 100));
        assert!(cache.get_ok(&third, 100));
    }
    #[test]
    fn cache_context_change_invalidates_entries() {
        let mut cache = StatelessValidationCache::new(4);
        let key = dummy_hash(9);
        cache.ensure_context(context(0xA1));
        cache.insert_ok(key, None, 0);
        assert!(cache.get_ok(&key, 100));
        cache.ensure_context(context(0xA1));
        assert!(cache.get_ok(&key, 100));
        cache.ensure_context(context(0xB2));
        assert!(!cache.get_ok(&key, 100));
        assert!(!cache.contains_key(&key));
    }
    fn context(seed: u8) -> StatelessValidationContext {
        StatelessValidationContext::new(
            NetworkId::from_genesis_hash(HashOf::<BlockHeader>::from_untyped_unchecked(
                Hash::prehashed([seed; Hash::LENGTH]),
            )),
            0,
            TransactionParameters::default(),
            vec![Algorithm::Ed25519],
        )
    }
}
/// Background persistor for DA shard cursor journals.
struct DaShardCursorJournalPersistor {
    inner: Arc<DaShardCursorJournalPersistorInner>,
    background_enabled: bool,
}
struct DaShardCursorJournalPersistorInner {
    pending: parking_lot::Mutex<Option<DaShardCursorJournal>>,
    cvar: parking_lot::Condvar,
    shutdown: AtomicBool,
}
impl DaShardCursorJournalPersistor {
    fn new() -> Self {
        let inner = Arc::new(DaShardCursorJournalPersistorInner {
            pending: parking_lot::Mutex::new(None),
            cvar: parking_lot::Condvar::new(),
            shutdown: AtomicBool::new(false),
        });
        let thread_inner = Arc::clone(&inner);
        let background_enabled = match std::thread::Builder::new()
            .name("da-shard-cursor-journal".to_string())
            .spawn(move || {
                loop {
                    let journal = {
                        let mut guard = thread_inner.pending.lock();
                        while guard.is_none() && !thread_inner.shutdown.load(Ordering::Relaxed) {
                            thread_inner.cvar.wait(&mut guard);
                        }
                        if guard.is_none() && thread_inner.shutdown.load(Ordering::Relaxed) {
                            return;
                        }
                        guard.take()
                    };
                    if let Some(journal) = journal {
                        if let Err(err) = journal.persist() {
                            warn!(?err, "failed to persist DA shard cursor journal");
                        }
                    }
                }
            }) {
            Ok(_handle) => true,
            Err(err) => {
                warn!(
                    ?err,
                    "failed to spawn DA shard cursor journal persistor; falling back to synchronous writes"
                );
                false
            }
        };
        Self {
            inner,
            background_enabled,
        }
    }
    fn schedule(&self, journal: DaShardCursorJournal) {
        if !self.background_enabled {
            if let Err(err) = journal.persist() {
                warn!(?err, "failed to persist DA shard cursor journal");
            }
            return;
        }
        let mut guard = self.inner.pending.lock();
        *guard = Some(journal);
        self.inner.cvar.notify_one();
    }
}
impl Drop for DaShardCursorJournalPersistor {
    fn drop(&mut self) {
        if !self.background_enabled {
            return;
        }
        self.inner.shutdown.store(true, Ordering::Relaxed);
        self.inner.cvar.notify_one();
    }
}
#[cfg(feature = "telemetry")]
fn record_tiered_snapshot_metrics(backend: &TieredStateBackend, telemetry: &StateTelemetry) {
    let manifest = backend.last_manifest().cloned();
    let hot_limit = backend.hot_retained_bytes();
    let cold_limit = backend.max_cold_bytes();
    let cold_store_bytes = match backend.cold_store_bytes() {
        Ok(value) => value,
        Err(err) => {
            warn!(?err, "tiered-state: failed to measure cold store bytes");
            None
        }
    };
    if let Some(manifest) = manifest {
        let hot_bytes = manifest.hot_entries.iter().fold(0u64, |acc, entry| {
            acc.saturating_add(entry.hot_budget_bytes())
        });
        crate::telemetry::record_state_tiered_snapshot(
            telemetry,
            manifest.snapshot_index,
            manifest.hot_entries.len(),
            hot_bytes,
            manifest.cold_entries.len(),
            manifest.cold_bytes_total,
            manifest.hot_promotions,
            manifest.hot_demotions,
            manifest.hot_budget_overflow_keys,
            manifest.hot_budget_overflow_bytes,
            manifest.cold_reused_entries,
            manifest.cold_reused_bytes,
        );
        telemetry.record_storage_budget_usage("wsv_hot", hot_bytes, hot_limit);
        if hot_limit > 0 && manifest.hot_budget_overflow_bytes > 0 {
            telemetry.inc_storage_budget_exceeded("wsv_hot");
        }
        if let Some(cold_used) = cold_store_bytes {
            telemetry.record_storage_budget_usage("wsv_cold", cold_used, cold_limit);
            if cold_limit > 0 && cold_used > cold_limit {
                telemetry.inc_storage_budget_exceeded("wsv_cold");
            }
        }
    }
}
/// Background worker for tiered snapshot processing.
struct TieredSnapshotWorker {
    inner: Arc<TieredSnapshotWorkerInner>,
    background_enabled: bool,
}
struct TieredSnapshotWorkerInner {
    backend: Arc<parking_lot::Mutex<TieredStateBackend>>,
    pending: parking_lot::Mutex<Option<TieredSnapshotPayload>>,
    cvar: parking_lot::Condvar,
    shutdown: AtomicBool,
    #[cfg(feature = "telemetry")]
    telemetry: Option<StateTelemetry>,
}
#[cfg(test)]
std::thread_local! {
    static TIERED_SNAPSHOT_WORKER_SPAWNS: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
}
impl TieredSnapshotWorker {
    fn inert(
        backend: Arc<parking_lot::Mutex<TieredStateBackend>>,
        #[cfg(feature = "telemetry")] telemetry: Option<StateTelemetry>,
    ) -> Self {
        Self {
            inner: Arc::new(TieredSnapshotWorkerInner {
                backend,
                pending: parking_lot::Mutex::new(None),
                cvar: parking_lot::Condvar::new(),
                shutdown: AtomicBool::new(false),
                #[cfg(feature = "telemetry")]
                telemetry,
            }),
            background_enabled: false,
        }
    }
    fn new(
        backend: Arc<parking_lot::Mutex<TieredStateBackend>>,
        #[cfg(feature = "telemetry")] telemetry: Option<StateTelemetry>,
    ) -> Self {
        #[cfg(test)]
        TIERED_SNAPSHOT_WORKER_SPAWNS.with(|count| count.set(count.get().saturating_add(1)));
        let inner = Arc::new(TieredSnapshotWorkerInner {
            backend,
            pending: parking_lot::Mutex::new(None),
            cvar: parking_lot::Condvar::new(),
            shutdown: AtomicBool::new(false),
            #[cfg(feature = "telemetry")]
            telemetry,
        });
        let thread_inner = Arc::clone(&inner);
        let background_enabled = match std::thread::Builder::new()
            .name("tiered-snapshot".to_string())
            .spawn(move || {
                loop {
                    let payload = {
                        let mut guard = thread_inner.pending.lock();
                        while guard.is_none() && !thread_inner.shutdown.load(Ordering::Relaxed) {
                            thread_inner.cvar.wait(&mut guard);
                        }
                        if guard.is_none() && thread_inner.shutdown.load(Ordering::Relaxed) {
                            return;
                        }
                        guard.take()
                    };
                    if let Some(payload) = payload {
                        let mut backend = thread_inner.backend.lock();
                        if let Err(err) = backend.record_world_snapshot_with_payload(&payload) {
                            warn!(?err, "tiered-state: failed to record snapshot");
                        }
                        #[cfg(feature = "telemetry")]
                        if let Some(telemetry) = thread_inner.telemetry.as_ref() {
                            record_tiered_snapshot_metrics(&backend, telemetry);
                        }
                    }
                }
            }) {
            Ok(_handle) => true,
            Err(err) => {
                warn!(
                    ?err,
                    "failed to spawn tiered snapshot worker; falling back to synchronous snapshots"
                );
                false
            }
        };
        Self {
            inner,
            background_enabled,
        }
    }
    fn enabled(&self) -> bool {
        self.background_enabled
    }
    fn schedule(&self, payload: TieredSnapshotPayload) -> bool {
        if !self.background_enabled {
            return false;
        }
        let mut guard = self.inner.pending.lock();
        *guard = Some(payload);
        self.inner.cvar.notify_one();
        true
    }
}
impl Drop for TieredSnapshotWorker {
    fn drop(&mut self) {
        if !self.background_enabled {
            return;
        }
        self.inner.shutdown.store(true, Ordering::Relaxed);
        self.inner.cvar.notify_one();
    }
}
const STATE_VIEW_LOCK_CONTENTION_WARN_COOLDOWN: Duration = Duration::from_secs(5);
const DIAGNOSTIC_STABLE_STATE_GENERATION_ATTEMPTS: usize = 4;
struct StateViewGenerationWriteGuard<'a> {
    generation: &'a AtomicU64,
}
impl Drop for StateViewGenerationWriteGuard<'_> {
    fn drop(&mut self) {
        let previous = self.generation.fetch_add(1, Ordering::AcqRel);
        debug_assert_eq!(
            previous % 2,
            1,
            "state view generation write guard must end from an active odd generation"
        );
    }
}
#[inline]
fn is_stable_state_view_generation(before: u64, after: u64) -> bool {
    before == after && after % 2 == 0
}
#[derive(Debug, Default)]
struct ViewLockContentionLog {
    last_warn_at: Option<Instant>,
    suppressed: u64,
}
impl ViewLockContentionLog {
    fn should_emit(&mut self, now: Instant, cooldown: Duration) -> Option<u64> {
        if let Some(last_warn_at) = self.last_warn_at {
            if cooldown > Duration::ZERO && now.saturating_duration_since(last_warn_at) < cooldown {
                self.suppressed = self.suppressed.saturating_add(1);
                return None;
            }
        }
        self.last_warn_at = Some(now);
        Some(std::mem::take(&mut self.suppressed))
    }
}
#[cfg(test)]
mod view_lock_contention_log_tests {
    use super::ViewLockContentionLog;
    use std::time::{Duration, Instant};
    #[test]
    fn contention_log_suppresses_within_cooldown_and_reports_aggregate() {
        let mut log = ViewLockContentionLog::default();
        let now = Instant::now();
        let cooldown = Duration::from_millis(50);
        assert_eq!(log.should_emit(now, cooldown), Some(0));
        assert_eq!(
            log.should_emit(now + Duration::from_millis(10), cooldown),
            None
        );
        assert_eq!(
            log.should_emit(now + Duration::from_millis(20), cooldown),
            None
        );
        assert_eq!(
            log.should_emit(now + Duration::from_millis(80), cooldown),
            Some(2)
        );
    }
}
/// Current state of the blockchain.
///
/// Merge-ledger finality plumbing is specified in `specs/merge_ledger.md`.
/// The lane/global reduction metadata exposed by the merge ledger is stored in
/// [`World::merge_hint_roots`] and [`World::merge_global_state_root`] so queries can
/// surface the latest committee commitments.
pub struct State {
    /// The world. Contains `domains`, `triggers`, `roles` and other data representing the current state of the blockchain.
    pub world: World,
    /// Blockchain.
    pub block_hashes: BlockHashes,
    /// Latest committed block header cached for hot paths that do not need full block bodies.
    latest_block_header: parking_lot::RwLock<Option<BlockHeader>>,
    /// Merge-ledger cache retaining recent entries for queries/telemetry.
    pub merge_ledger: MergeLedgerStore,
    /// Atomic authority for merge epoch, binding, relay-tip, and execution progression.
    merge_admission: parking_lot::RwLock<MergeAdmissionState>,
    /// Immutable merge carriers authenticated once for the active startup replay bundle.
    replay_merge_carriers:
        parking_lot::RwLock<BTreeMap<HashOf<MergeLedgerEntry>, ReplayMergeCarrier>>,
    /// Hashes of transactions mapped onto block height where they stored
    pub transactions: TransactionsStorage,
    /// Topology used to commit latest block
    pub commit_topology: Cell<Vec<PeerId>>,
    /// Topology used to commit previous block
    pub prev_commit_topology: Cell<Vec<PeerId>>,
    /// Ledger-derived DA commitment index hydrated from committed Kura blocks.
    pub da_commitments: parking_lot::RwLock<DaCommitmentStore>,
    /// In-memory confidential-compute receipt index derived from DA commitments.
    pub da_confidential_compute: parking_lot::RwLock<ConfidentialComputeStore>,
    /// In-memory DA receipt cursor index reconstructed from committed DA bundles.
    pub da_receipt_cursors: parking_lot::RwLock<DaReceiptCursorIndex>,
    /// In-memory DA shard cursor index reconstructed from committed DA bundles.
    pub da_shard_cursors: parking_lot::RwLock<DaShardCursorIndex>,
    /// Background persistor for DA shard cursor journal snapshots.
    da_shard_cursor_persistor: DaShardCursorJournalPersistor,
    /// Durable latest query-index snapshot marker reconstructed at startup.
    query_index_journal: parking_lot::RwLock<QueryIndexJournal>,
    /// Serializes the complete query-index journal persistence and accounting scope.
    query_index_journal_persistence_lock: parking_lot::Mutex<()>,
    /// Durable latest query projection checkpoint descriptor reconstructed at startup.
    query_projection_checkpoint_journal: parking_lot::RwLock<QueryProjectionCheckpointJournal>,
    /// Serializes the complete projection-checkpoint journal persistence and accounting scope.
    query_projection_checkpoint_journal_persistence_lock: parking_lot::Mutex<()>,
    /// In-memory DA pin intent index mirrored from the on-chain registry.
    pub da_pin_intents: parking_lot::RwLock<DaPinStore>,
    /// In-memory lane relay envelope cache used for merge/telemetry.
    pub lane_relays: parking_lot::RwLock<LaneRelayStore>,
    /// Receipt source ids already burned through merge settlement in this process.
    pub settled_nexus_fee_receipts: parking_lot::RwLock<BTreeSet<[u8; 32]>>,
    /// Lane governance manifest registry snapshot used for lane-relay validation.
    pub lane_manifests: parking_lot::RwLock<LaneManifestRegistryHandle>,
    /// Lane privacy commitment registry derived from governance manifests.
    pub lane_privacy_registry: parking_lot::RwLock<LanePrivacyRegistryHandle>,
    /// Optional lane compliance engine (consensus-critical when configured).
    lane_compliance: parking_lot::RwLock<Option<Arc<LaneComplianceEngine>>>,
    /// Serializes initial DA hydration and every explicit rewind rebuild.
    da_index_hydration_fence: parking_lot::Mutex<()>,
    /// Cached outcome of the most recent serialized DA index rebuild.
    da_indexes_hydrated: parking_lot::RwLock<Option<Result<(), DaIndexHydrationError>>>,
    /// Runtime handle for the IVM to execute triggers.
    pub ivm: IVM,
    /// Reference to Kura subsystem.
    kura: Arc<Kura>,
    /// Handle to the [`LiveQueryStore`](crate::query::store::LiveQueryStore).
    pub query_handle: LiveQueryStoreHandle,
    /// Pipeline execution preferences (dynamic prepass, parallel overlay).
    pub pipeline: iroha_config::parameters::actual::Pipeline,
    /// Shared pipeline worker pool snapshot (derived from pipeline config).
    pipeline_parallelism: PipelineParallelism,
    /// Optional shared Soracloud runtime handle used for replicated mailbox execution.
    soracloud_runtime:
        parking_lot::RwLock<Option<crate::soracloud_runtime::SharedSoracloudRuntime>>,
    /// Stateless validation cache shared across blocks.
    stateless_validation_cache: parking_lot::Mutex<StatelessValidationCache>,
    /// Cache for IVM trigger program summaries and runtime templates.
    trigger_ivm_cache: parking_lot::Mutex<IvmCache>,
    /// Isolated cache for Torii contract preparation, views, and simulations.
    ///
    /// Keeping public query traffic separate prevents an untrusted stream of
    /// distinct contracts from evicting consensus-path trigger runtimes.
    contract_query_ivm_cache: parking_lot::Mutex<IvmCache>,
    /// Process-persistent immutable artifacts and runtimes shared by pipeline workers.
    pipeline_ivm_prepared_cache: parking_lot::RwLock<PreparedContractCache>,
    /// Oracle aggregation configuration.
    pub oracle: iroha_config::parameters::actual::Oracle,
    /// Process-local streaming spool paths used by storage-budget enforcement.
    streaming_storage_paths: StreamingStoragePaths,
    /// Cryptography configuration (enabled algorithms, defaults).
    pub crypto: parking_lot::RwLock<Arc<iroha_config::parameters::actual::Crypto>>,
    /// Nexus configuration snapshot (lanes, fusion, DA policies).
    ///
    /// Stored behind a lock so Torii/app-side lifecycle handlers can update the lane catalog at
    /// runtime without requiring exclusive ownership of the whole `State`.
    pub nexus: parking_lot::RwLock<iroha_config::parameters::actual::Nexus>,
    /// Active incarnation commitment for every lane in the effective catalog.
    lane_incarnations: parking_lot::RwLock<BTreeMap<LaneId, Hash>>,
    /// Latest incarnation commitment ever assigned to each lane id, including retired lanes.
    ///
    /// Retaining this lineage prevents an identical lane configuration from reproducing an old
    /// incarnation after retirement and recreation.
    lane_incarnation_lineage: parking_lot::RwLock<BTreeMap<LaneId, LaneIncarnationLineage>>,
    /// Global activation height for every active lane incarnation (`0` for static lanes).
    lane_incarnation_activation_heights: parking_lot::RwLock<BTreeMap<LaneId, u64>>,
    /// Whether the effective Nexus runtime catalog came from the loaded WSV snapshot.
    nexus_runtime_restored_from_snapshot: bool,
    /// Last block height where Nexus storage budget enforcement ran.
    nexus_storage_budget_last_check_height: AtomicU64,
    /// Bounded canonical inputs used by deterministic Nexus autoscale windows.
    autoscale_sample_history: parking_lot::RwLock<VecDeque<AutoscaleSampleRecord>>,
    /// Tiered state backend coordinating hot/cold snapshots.
    pub tiered_backend: Arc<parking_lot::Mutex<TieredStateBackend>>,
    /// Background worker for tiered snapshot processing.
    tiered_snapshot_worker: TieredSnapshotWorker,
    /// Fraud monitoring configuration snapshot.
    pub fraud_monitoring: iroha_config::parameters::actual::FraudMonitoring,
    /// Zero-knowledge verification configuration (Halo2 backend limits, etc.).
    pub zk: iroha_config::parameters::actual::Zk,
    /// Parsed SCCP on-chain registry cached by authoritative JSON allocation.
    sccp_registry_cache: parking_lot::Mutex<SccpRegistryCache>,
    /// Governance configuration (voting keys, policies).
    pub gov: iroha_config::parameters::actual::Governance,
    /// Content lane configuration (bundle caps, chunk size).
    pub content: iroha_config::parameters::actual::Content,
    /// Settlement configuration (repo defaults, collateral policies).
    pub settlement: iroha_config::parameters::actual::Settlement,
    /// Immutable startup-authenticated ABI-21 recursive release catalog.
    pub kagemusha_release_catalog:
        Arc<crate::smartcontracts::isi::offline::KagemushaReleaseCatalogV4>,
    /// Startup-authenticated complete runtime projection used only by local consensus gates.
    kagemusha_runtime_effective_config_sha256: SyncOnceCell<[u8; 32]>,
    /// Unified settlement engine for XOR quoting.
    pub settlement_engine: crate::settlement::SettlementEngine,
    /// Display chain identifier from configuration, exposed through the display sysvar.
    pub chain_id: iroha_data_model::ChainId,
    /// Exact transaction security domain derived from `genesis.expected_hash`; binds VRF prehashes.
    pub network_id: iroha_data_model::NetworkId,
    /// Typed v2 trust root parsed from a snapshot but not yet authorized by snapshot policy.
    snapshot_v2_bootstrap_candidate: Option<SnapshotV2BootstrapRecord>,
    /// Snapshot-policy-authorized and WSV-validated v2 trust root.
    authenticated_snapshot_v2_bootstrap: Option<SnapshotV2BootstrapRecord>,
    /// Non-forgeable outer snapshot authentication proof retained for startup upgrade.
    authenticated_snapshot_bootstrap_payload:
        Option<crate::snapshot::AuthenticatedSnapshotBootstrapPayload>,
    /// State telemetry sink mirrored from data events.
    #[cfg(feature = "telemetry")]
    pub telemetry: StateTelemetry,
    /// Lock serializing lane lifecycle storage reconciliation with state commits.
    lane_lifecycle_lock: parking_lot::Mutex<()>,
    /// Lock serializing complete block commits across fallible pre-publication work.
    state_commit_lock: Arc<parking_lot::Mutex<()>>,
    /// Lock serializing writer commit phases that mutate several state components.
    state_write_lock: parking_lot::Mutex<()>,
    /// Even generation means no writer is committing; odd generation means retry full state views.
    view_generation: AtomicU64,
    /// Aggregates repeated view-generation contention warnings to avoid log spam under write pressure.
    view_lock_contention_log: parking_lot::Mutex<ViewLockContentionLog>,
}
#[derive(Clone, Debug, PartialEq, Eq)]
struct ReplayMergeCarrier {
    block_height: u64,
    block_hash: HashOf<BlockHeader>,
    entry: MergeLedgerEntry,
}
type AutonomousLaneDiagnosticKey = (LaneId, DataSpaceId, Hash, u64, u64, u64, Hash);
#[derive(Clone)]
struct AutonomousLaneDiagnosticEvidence {
    row: SumeragiAutonomousLaneExecution,
    reservation_keys: Option<Vec<crate::queue::LaneQueueReservationKeyV2>>,
    reservations_durable: bool,
    payload_durable: bool,
    availability_certified: bool,
    lane_certified: bool,
    bundle_durable: bool,
    merge_candidate: bool,
    globally_committed: bool,
    application_receipt: bool,
    queue_finalized: bool,
    conflict: bool,
}
impl AutonomousLaneDiagnosticEvidence {
    fn from_reservation_group(
        summary: crate::queue::LaneQueueReservationDiagnosticGroupV1,
    ) -> Self {
        let binding = summary.binding;
        let identity = binding.identity;
        Self {
            row: SumeragiAutonomousLaneExecution {
                lane_id: identity.lane_id,
                dataspace_id: identity.dataspace_id,
                lane_incarnation: identity.lane_incarnation,
                lane_block_height: identity.lane_block_height,
                lane_block_view: identity.lane_block_view,
                proposal_height: identity.proposal_height,
                proposal_view: None,
                reservation_owner_hash: identity.reservation_owner_hash,
                proposal_identity_hash: identity.proposal_identity_hash,
                reservation_group_hash: binding.reservation_group_hash,
                proposal_hash: None,
                descriptor_hash: None,
                executable_payload_hash: None,
                source_bundle_hash: None,
                merge_entry_hash: None,
                application_block_height: None,
                application_block_hash: None,
                reservation_count: binding.reservation_count,
                transaction_count: binding.reservation_count,
                highest_durable_stage: SumeragiAutonomousLaneExecutionStage::ReservationsDurable,
                stuck_reason: None,
            },
            reservation_keys: None,
            reservations_durable: true,
            payload_durable: false,
            availability_certified: false,
            lane_certified: false,
            bundle_durable: false,
            merge_candidate: false,
            globally_committed: false,
            application_receipt: false,
            queue_finalized: false,
            conflict: summary.conflict,
        }
    }
    fn from_proposal_and_reservations(
        proposal: &iroha_data_model::block::consensus::LaneBlockProposalV1,
        reservation_keys: &[crate::queue::LaneQueueReservationKeyV2],
    ) -> Result<Self> {
        let descriptor = &proposal.descriptor;
        let transaction_count = u64::try_from(descriptor.accepted_transaction_hashes.len())
            .map_err(|_| eyre!("autonomous proposal transaction count does not fit u64"))?;
        let binding = crate::queue::lane_queue_reservation_group_binding_from_ordered_keys(
            reservation_keys.iter(),
        )
        .map_err(|reason| eyre!(reason))?;
        let identity = binding.identity;
        let reservation_count = binding.reservation_count;
        let conflict = transaction_count == 0
            || descriptor.accepted_candidate_indices.len()
                != descriptor.accepted_transaction_hashes.len()
            || transaction_count != reservation_count
            || descriptor.lane_id != identity.lane_id
            || descriptor.dataspace_id != identity.dataspace_id
            || descriptor.lane_incarnation != identity.lane_incarnation
            || descriptor.proposal_height != identity.proposal_height
            || descriptor.lane_block_height != identity.lane_block_height
            || descriptor.lane_block_view != identity.lane_block_view
            || descriptor
                .accepted_transaction_hashes
                .iter()
                .zip(reservation_keys)
                .any(|(accepted, key)| *accepted != Hash::from(key.entrypoint_hash));
        Ok(Self {
            row: SumeragiAutonomousLaneExecution {
                lane_id: identity.lane_id,
                dataspace_id: identity.dataspace_id,
                lane_incarnation: identity.lane_incarnation,
                lane_block_height: identity.lane_block_height,
                lane_block_view: identity.lane_block_view,
                proposal_height: identity.proposal_height,
                proposal_view: proposal.payload_block_hint.map(|hint| hint.proposal_view),
                reservation_owner_hash: identity.reservation_owner_hash,
                proposal_identity_hash: identity.proposal_identity_hash,
                reservation_group_hash: binding.reservation_group_hash,
                proposal_hash: Some(proposal.proposal_hash),
                descriptor_hash: Some(descriptor.descriptor_hash),
                executable_payload_hash: None,
                source_bundle_hash: None,
                merge_entry_hash: None,
                application_block_height: None,
                application_block_hash: None,
                reservation_count,
                transaction_count,
                highest_durable_stage: SumeragiAutonomousLaneExecutionStage::LaneCertified,
                stuck_reason: None,
            },
            reservation_keys: Some(reservation_keys.to_vec()),
            reservations_durable: false,
            payload_durable: false,
            availability_certified: false,
            lane_certified: false,
            bundle_durable: false,
            merge_candidate: false,
            globally_committed: false,
            application_receipt: false,
            queue_finalized: false,
            conflict,
        })
    }
    fn key(&self) -> AutonomousLaneDiagnosticKey {
        self.row.ordering_key()
    }
    fn exact_reservation_keys(&self) -> Option<&[crate::queue::LaneQueueReservationKeyV2]> {
        let keys = self.reservation_keys.as_deref()?;
        let count = u64::try_from(keys.len()).ok()?;
        let binding =
            crate::queue::lane_queue_reservation_group_binding_from_ordered_keys(keys.iter())
                .ok()?;
        if count != self.row.reservation_count
            || count != self.row.transaction_count
            || binding.reservation_group_hash != self.row.reservation_group_hash
            || binding.identity.lane_id != self.row.lane_id
            || binding.identity.dataspace_id != self.row.dataspace_id
            || binding.identity.lane_incarnation != self.row.lane_incarnation
            || binding.identity.proposal_height != self.row.proposal_height
            || binding.identity.lane_block_height != self.row.lane_block_height
            || binding.identity.lane_block_view != self.row.lane_block_view
            || binding.identity.reservation_owner_hash != self.row.reservation_owner_hash
            || binding.identity.proposal_identity_hash != self.row.proposal_identity_hash
        {
            return None;
        }
        Some(keys)
    }
    fn merge(&mut self, other: Self) {
        if self.row.transaction_count != other.row.transaction_count {
            self.conflict = true;
        }
        match (self.row.proposal_view, other.row.proposal_view) {
            (Some(current), Some(incoming)) if current != incoming => self.conflict = true,
            (None, incoming) => self.row.proposal_view = incoming,
            _ => {}
        }
        if self.row.reservation_owner_hash != other.row.reservation_owner_hash {
            self.conflict = true;
            self.row.reservation_owner_hash = self
                .row
                .reservation_owner_hash
                .min(other.row.reservation_owner_hash);
        }
        if self.row.reservation_group_hash != other.row.reservation_group_hash {
            self.conflict = true;
            self.row.reservation_group_hash = self
                .row
                .reservation_group_hash
                .min(other.row.reservation_group_hash);
        }
        match (
            (self.row.proposal_hash, self.row.descriptor_hash),
            (other.row.proposal_hash, other.row.descriptor_hash),
        ) {
            (
                (Some(current_proposal), Some(current_descriptor)),
                (Some(incoming_proposal), Some(incoming_descriptor)),
            ) => {
                if current_proposal != incoming_proposal
                    || current_descriptor != incoming_descriptor
                {
                    self.conflict = true;
                }
            }
            ((None, None), (Some(proposal_hash), Some(descriptor_hash))) => {
                self.row.proposal_hash = Some(proposal_hash);
                self.row.descriptor_hash = Some(descriptor_hash);
            }
            ((Some(_), Some(_)), (None, None)) | ((None, None), (None, None)) => {}
            _ => self.conflict = true,
        }
        for (current, incoming) in [
            (
                &mut self.row.executable_payload_hash,
                other.row.executable_payload_hash,
            ),
            (
                &mut self.row.source_bundle_hash,
                other.row.source_bundle_hash,
            ),
        ] {
            if current.is_some() && incoming.is_some() && *current != incoming {
                self.conflict = true;
            } else if current.is_none() {
                *current = incoming;
            }
        }
        if self.row.merge_entry_hash.is_some()
            && other.row.merge_entry_hash.is_some()
            && self.row.merge_entry_hash != other.row.merge_entry_hash
        {
            self.conflict = true;
        } else if self.row.merge_entry_hash.is_none() {
            self.row.merge_entry_hash = other.row.merge_entry_hash;
        }
        if self.row.application_block_height.is_some()
            && other.row.application_block_height.is_some()
            && (self.row.application_block_height != other.row.application_block_height
                || self.row.application_block_hash != other.row.application_block_hash)
        {
            self.conflict = true;
        } else if self.row.application_block_height.is_none() {
            self.row.application_block_height = other.row.application_block_height;
            self.row.application_block_hash = other.row.application_block_hash;
        }
        if self.row.reservation_count != 0
            && other.row.reservation_count != 0
            && self.row.reservation_count != other.row.reservation_count
        {
            self.conflict = true;
        } else {
            self.row.reservation_count =
                self.row.reservation_count.max(other.row.reservation_count);
        }
        match (&self.reservation_keys, other.reservation_keys) {
            (Some(current), Some(incoming)) if *current != incoming => {
                self.conflict = true;
            }
            (None, incoming) => {
                self.reservation_keys = incoming;
            }
            _ => {}
        }
        self.reservations_durable |= other.reservations_durable;
        self.payload_durable |= other.payload_durable;
        self.availability_certified |= other.availability_certified;
        self.lane_certified |= other.lane_certified;
        self.bundle_durable |= other.bundle_durable;
        self.merge_candidate |= other.merge_candidate;
        self.globally_committed |= other.globally_committed;
        self.application_receipt |= other.application_receipt;
        self.queue_finalized |= other.queue_finalized;
        self.conflict |= other.conflict;
    }
    fn finish(mut self) -> SumeragiAutonomousLaneExecution {
        let (stage, reason) = if self.conflict {
            (
                SumeragiAutonomousLaneExecutionStage::Conflict,
                Some(SumeragiAutonomousLaneExecutionStuckReason::EvidenceConflict),
            )
        } else if self.application_receipt && self.queue_finalized {
            (SumeragiAutonomousLaneExecutionStage::QueueFinalized, None)
        } else if self.application_receipt {
            (
                SumeragiAutonomousLaneExecutionStage::KuraWsvApplicationReceiptDurable,
                Some(SumeragiAutonomousLaneExecutionStuckReason::QueueFinalizationUnverifiable),
            )
        } else if self.globally_committed {
            (
                SumeragiAutonomousLaneExecutionStage::GlobalCarrierCommitted,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingApplicationReceipt),
            )
        } else if self.merge_candidate {
            (
                SumeragiAutonomousLaneExecutionStage::MergeCandidateDurable,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingGlobalCarrier),
            )
        } else if self.bundle_durable {
            (
                SumeragiAutonomousLaneExecutionStage::CertifiedBundleDurable,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingMergeSelection),
            )
        } else if self.lane_certified {
            (
                SumeragiAutonomousLaneExecutionStage::LaneCertified,
                Some(SumeragiAutonomousLaneExecutionStuckReason::CertifiedBundleUnavailable),
            )
        } else if self.availability_certified {
            (
                SumeragiAutonomousLaneExecutionStage::PayloadAvailabilityCertified,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingLaneCertification),
            )
        } else if self.payload_durable {
            (
                SumeragiAutonomousLaneExecutionStage::ExecutablePayloadDurable,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingPayloadAvailability),
            )
        } else if self.reservations_durable
            && self.row.reservation_count == self.row.transaction_count
        {
            (
                SumeragiAutonomousLaneExecutionStage::ReservationsDurable,
                Some(SumeragiAutonomousLaneExecutionStuckReason::AwaitingExecutablePayload),
            )
        } else {
            (
                SumeragiAutonomousLaneExecutionStage::Conflict,
                Some(SumeragiAutonomousLaneExecutionStuckReason::EvidenceConflict),
            )
        };
        self.row.highest_durable_stage = stage;
        self.row.stuck_reason = reason;
        self.row
    }
}
struct LoadedStateJournals {
    query_index: QueryIndexJournal,
    query_projection_checkpoint: QueryProjectionCheckpointJournal,
}
fn load_state_journals(
    kura: &Kura,
    canonical_query_index_status: Option<QueryIndexStatus>,
    allow_durable_recovery: bool,
) -> LoadedStateJournals {
    let store_root = kura.store_root();
    // Journal loaders may promote a fully written recovery temporary and
    // remove stale files. Snapshot bootstrap opens the whole Kura tree as an
    // authenticated read-only candidate, so retain process-local empty
    // journals until the token-consuming Kura finalizer has completed.
    if !allow_durable_recovery || kura.provisional_snapshot_bootstrap_pending() {
        let mut query_index = QueryIndexJournal::new(QueryIndexJournal::journal_path(&store_root));
        if let Some(status) = canonical_query_index_status {
            query_index.set_latest(status.indexed_height, status.indexed_block_hash);
        }
        return LoadedStateJournals {
            query_index,
            query_projection_checkpoint: QueryProjectionCheckpointJournal::new(
                QueryProjectionCheckpointJournal::journal_path(&store_root),
            ),
        };
    }
    let accounting_mutation = kura.begin_total_disk_usage_mutation();
    let query_index_path = QueryIndexJournal::journal_path(&store_root);
    let mut query_index = match QueryIndexJournal::load(query_index_path.clone()) {
        Ok(journal) => journal,
        Err(err) => {
            warn!(
                ?err,
                path = %query_index_path.display(),
                "failed to load query index journal; starting empty"
            );
            QueryIndexJournal::new(query_index_path)
        }
    };
    if let Some(status) = canonical_query_index_status {
        query_index.set_latest(status.indexed_height, status.indexed_block_hash);
    }
    let query_projection_checkpoint_path =
        QueryProjectionCheckpointJournal::journal_path(&store_root);
    let query_projection_checkpoint =
        match QueryProjectionCheckpointJournal::load(query_projection_checkpoint_path.clone()) {
            Ok(journal) => journal,
            Err(err) => {
                warn!(
                    ?err,
                    path = %query_projection_checkpoint_path.display(),
                    "failed to load query projection checkpoint journal; starting empty"
                );
                QueryProjectionCheckpointJournal::new(query_projection_checkpoint_path)
            }
        };
    // Loading a valid temp journal can replace and remove files. Dropping an unpublished
    // mutation invalidates both caches before the synchronous stable scan republishes them.
    drop(accounting_mutation);
    if let Err(err) = kura.refresh_disk_usage_bytes() {
        warn!(
            ?err,
            "failed to reconcile Kura disk usage after state journal recovery"
        );
    }
    LoadedStateJournals {
        query_index,
        query_projection_checkpoint,
    }
}
/// Deterministic SCCP verifier work reserved by accepted transactions.
///
/// Counts are hardware-independent upper bounds derived from canonical proof framing before any
/// signature recovery, aggregate verification, or pairing dispatch.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct SccpVerifierWorkV1 {
    /// Closed SCCP proof count.
    pub(crate) proofs: u64,
    /// Canonical closed SCCP proof bytes.
    pub(crate) proof_bytes: u64,
    /// BSC/TRON native-finality continuation headers.
    pub(crate) native_headers: u64,
    /// Ethereum native light-client updates.
    pub(crate) ethereum_light_client_updates: u64,
    /// Framed native-finality material bytes.
    pub(crate) native_header_bytes: u64,
    /// secp256k1 public-key recoveries.
    pub(crate) secp256k1_recoveries: u64,
    /// BLS aggregate-signature verification calls.
    pub(crate) bls_aggregate_checks: u64,
    /// BLS public-key validation or aggregate-contribution work items.
    pub(crate) bls_signer_contributions: u64,
    /// BN254 Groth16 pairing-product verification calls.
    pub(crate) bn254_pairing_checks: u64,
}
impl SccpVerifierWorkV1 {
    fn checked_add(self, other: Self) -> Option<Self> {
        Some(Self {
            proofs: self.proofs.checked_add(other.proofs)?,
            proof_bytes: self.proof_bytes.checked_add(other.proof_bytes)?,
            native_headers: self.native_headers.checked_add(other.native_headers)?,
            ethereum_light_client_updates: self
                .ethereum_light_client_updates
                .checked_add(other.ethereum_light_client_updates)?,
            native_header_bytes: self
                .native_header_bytes
                .checked_add(other.native_header_bytes)?,
            secp256k1_recoveries: self
                .secp256k1_recoveries
                .checked_add(other.secp256k1_recoveries)?,
            bls_aggregate_checks: self
                .bls_aggregate_checks
                .checked_add(other.bls_aggregate_checks)?,
            bls_signer_contributions: self
                .bls_signer_contributions
                .checked_add(other.bls_signer_contributions)?,
            bn254_pairing_checks: self
                .bn254_pairing_checks
                .checked_add(other.bn254_pairing_checks)?,
        })
    }
    #[cfg(test)]
    fn is_zero(self) -> bool {
        self == Self::default()
    }
}
/// Topology authority governing post-execution State publication.
#[derive(Clone)]
enum ApplyTopologyAuthority {
    /// Nonshipping fixtures may exercise caller-supplied topology reconciliation.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    Fixture,
    /// Exact Sumeragi-v2 finality remains authoritative.
    V2Finality,
}
/// Immutable AXT authorization snapshot captured before block effects.
/// Freezes policy and issuer/key state; accepted handles separately advance
/// counters. Replay and budget records are hydrated on demand from the parent
/// MVCC undo log so block construction is not linear in historical entries.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AxtBlockStartSnapshot {
    policy_snapshot: AxtPolicySnapshot,
    issuer_bindings: BTreeMap<
        DataSpaceId,
        Result<
            crate::nexus::space_directory::AxtIssuerBinding,
            crate::nexus::space_directory::AxtIssuerResolutionError,
        >,
    >,
    lane_incarnations: BTreeMap<DataSpaceId, Option<Hash>>,
}
/// Complete block-local identity whose replacement revokes unused AXT nonces.
#[derive(Clone, Debug, PartialEq, Eq)]
struct AxtAuthorizationId {
    manifest_root: [u8; 32],
    target_lane: LaneId,
    active_handle_era: u64,
    issuer: Result<
        crate::nexus::space_directory::AxtIssuerBinding,
        crate::nexus::space_directory::AxtIssuerResolutionError,
    >,
}
fn axt_authorization_identities(
    world: &(impl WorldReadOnly + ?Sized),
) -> BTreeMap<DataSpaceId, AxtAuthorizationId> {
    world
        .axt_policies()
        .iter()
        .filter(|(_, policy)| axt_policy_is_active(policy))
        .map(|(dataspace, policy)| {
            (
                *dataspace,
                AxtAuthorizationId {
                    manifest_root: policy.manifest_root,
                    target_lane: policy.target_lane,
                    active_handle_era: policy.active_handle_era,
                    issuer: crate::nexus::space_directory::resolve_axt_issuer_binding(
                        world,
                        *dataspace,
                        policy.manifest_root,
                    ),
                },
            )
        })
        .collect()
}

/// Project permanent per-dataspace handle counters into a policy snapshot.
///
/// Policy rows are replaceable routing/manifest projections; their embedded
/// counter is only a cache. The separate ratchet is consensus authority and
/// therefore wins across manifest rotation, lane rebind, and policy removal.
pub(crate) fn project_axt_handle_counters(
    world: &(impl WorldReadOnly + ?Sized),
    snapshot: &mut AxtPolicySnapshot,
) {
    let counters = world.axt_handle_counters();
    for binding in &mut snapshot.entries {
        if let Some(record) = counters.get(&binding.dsid) {
            binding.policy.next_handle_counter = record.next();
            binding.policy.active_handle_era = record.authorization_generation();
        }
    }
    snapshot.version = AxtPolicySnapshot::compute_version(&snapshot.entries);
}

impl AxtBlockStartSnapshot {
    fn capture(state_block: &StateBlock<'_>) -> Self {
        let mut policy_snapshot = WorldReadOnly::axt_policy_snapshot(state_block.world());
        if policy_snapshot.entries.is_empty() {
            policy_snapshot = crate::smartcontracts::ivm::host::CoreHost::derive_axt_policy_snapshot_from_directory(
                state_block,
            )
            .unwrap_or_default();
        }
        project_axt_handle_counters(state_block.world(), &mut policy_snapshot);
        let current_slot = current_axt_slot_from_block(
            &state_block._curr_block,
            state_block.nexus.axt.slot_length_ms,
        );
        for binding in &mut policy_snapshot.entries {
            binding.policy.current_slot = current_slot;
        }
        policy_snapshot.version = AxtPolicySnapshot::compute_version(&policy_snapshot.entries);
        policy_snapshot
            .validate()
            .expect("block-start AXT policy projection must be canonical");
        let issuer_bindings = policy_snapshot
            .entries
            .iter()
            .map(|binding| {
                (
                    binding.dsid,
                    crate::nexus::space_directory::resolve_axt_issuer_binding(
                        state_block.world(),
                        binding.dsid,
                        binding.policy.manifest_root,
                    ),
                )
            })
            .collect();
        let lane_incarnations = policy_snapshot
            .entries
            .iter()
            .map(|binding| {
                (
                    binding.dsid,
                    state_block
                        .lane_incarnations
                        .get(&binding.policy.target_lane)
                        .copied(),
                )
            })
            .collect();
        Self {
            policy_snapshot,
            issuer_bindings,
            lane_incarnations,
        }
    }
    /// Return the exact policy identity and initial counters captured at block start.
    #[must_use]
    pub const fn policy_snapshot(&self) -> &AxtPolicySnapshot {
        &self.policy_snapshot
    }
    /// Resolve the issuer identity and verification key captured for `dataspace`.
    ///
    /// # Errors
    ///
    /// Returns the deterministic resolution failure captured from the pre-block
    /// state, or [`crate::nexus::space_directory::AxtIssuerResolutionError::MissingManifest`]
    /// when the dataspace had no block-start policy entry.
    pub fn issuer_binding(
        &self,
        dataspace: DataSpaceId,
    ) -> Result<
        &crate::nexus::space_directory::AxtIssuerBinding,
        crate::nexus::space_directory::AxtIssuerResolutionError,
    > {
        self.issuer_bindings
            .get(&dataspace)
            .ok_or(crate::nexus::space_directory::AxtIssuerResolutionError::MissingManifest)?
            .as_ref()
            .map_err(|error| *error)
    }
    pub(crate) fn authorization_identity_changed(
        &self,
        world: &(impl WorldReadOnly + ?Sized),
        final_lane_incarnations: &BTreeMap<LaneId, Hash>,
        dataspace: DataSpaceId,
        final_policy: Option<&AxtPolicyEntry>,
    ) -> bool {
        let previous_policy = self
            .policy_snapshot
            .entries
            .iter()
            .find(|binding| binding.dsid == dataspace)
            .map(|binding| &binding.policy);
        if axt_policy_identity_changed(previous_policy, final_policy) {
            return true;
        }
        let (Some(previous_policy), Some(final_policy)) = (previous_policy, final_policy) else {
            return false;
        };
        if !axt_policy_is_active(previous_policy) {
            return false;
        }
        let previous_issuer = self.issuer_bindings.get(&dataspace);
        let final_issuer = crate::nexus::space_directory::resolve_axt_issuer_binding(
            world,
            dataspace,
            final_policy.manifest_root,
        );
        if previous_issuer != Some(&final_issuer) {
            return true;
        }
        let previous_incarnation = self.lane_incarnations.get(&dataspace).copied().flatten();
        let final_incarnation = final_lane_incarnations
            .get(&final_policy.target_lane)
            .copied();
        previous_incarnation != final_incarnation
    }
    fn policy_with_counters(&self, counters: &BTreeMap<DataSpaceId, u64>) -> AxtPolicySnapshot {
        let mut snapshot = self.policy_snapshot.clone();
        for binding in &mut snapshot.entries {
            if let Some(counter) = counters.get(&binding.dsid) {
                binding.policy.next_handle_counter = *counter;
            }
        }
        snapshot.version = AxtPolicySnapshot::compute_version(&snapshot.entries);
        snapshot
    }
}
/// Move-only proof that this block overlay is the exact canonical WSV transition
/// re-executed from one certified autonomous merge batch.
#[derive(Debug)]
struct CanonicalWsvMergeCommitAuthorization {
    entry_hash: HashOf<MergeLedgerEntry>,
    carrier_height: u64,
    carrier_hash: HashOf<BlockHeader>,
    base_state_height: u64,
    base_state_hash: HashOf<BlockHeader>,
    batch_hash: Hash,
    write_set_root: Hash,
    expected_post_state_hash: HashOf<BlockHeader>,
    /// Exact autonomous execution events committed by `write_set_root`.
    ///
    /// Block application drains these transient events for publication before
    /// the State commit boundary. Retaining their exact encoding lets the
    /// final authorization reconstruct the certified write-set without either
    /// suppressing observable events or accepting a different event surface.
    external_event_bytes: Option<Vec<u8>>,
    /// Number of leading block events produced by the autonomous execution.
    ///
    /// Ordinary deterministic carrier processing may append events (most
    /// notably the canonical time event). The prefix length keeps those events
    /// outside the merge write-set while proving that the QC-bound autonomous
    /// events were neither removed nor reordered.
    external_event_count: usize,
    /// Exact complete event surface observed after deterministic carrier
    /// processing and before consensus may vote.
    ///
    /// `None` means the post-block surface has not been authorized yet. Once
    /// present, final application must observe these bytes unchanged before it
    /// appends the ordinary Applied block event and publishes the buffer.
    validated_publication_event_bytes: Option<Vec<u8>>,
}
/// Exact carrier metadata permitted at each autonomous merge execution boundary.
///
/// Candidate construction and certified-entry staging run before the canonical
/// transaction-height index is touched. Full block validation must then stage
/// one exact empty carrier row before voting, and final application must bind
/// both that row and the finalized carrier hash. This transient validation-only
/// view is never persisted or serialized; keeping the phases distinct prevents
/// rejection of valid carriers or acceptance of arbitrary block metadata.
#[derive(Debug, Clone, Copy)]
enum MergeExecutionCommitSurface<'carrier> {
    Pristine,
    PostBlockPreVote {
        carrier_height: u64,
    },
    FinalizedCarrier {
        carrier_height: u64,
        carrier_hash: &'carrier HashOf<BlockHeader>,
    },
}
/// Move-only proof of exact finalized carrier metadata and post-finality WSV.
#[derive(Debug)]
struct CanonicalCarrierCommitMetadataAuthorization {
    entry_hash: HashOf<MergeLedgerEntry>,
    carrier_height: u64,
    carrier_hash: HashOf<BlockHeader>,
    post_finality_write_set_root: Hash,
    previous_commit_topology: Vec<PeerId>,
    next_commit_topology: Vec<PeerId>,
    autoscale_sample: AutoscaleSampleRecord,
}
/// Move-only authorization consumed at the canonical State commit boundary.
///
/// Implementations must bind the finalized carrier identity to the exact
/// autonomous merge entry staged in this [`StateBlock`]. State consumes the
/// authorization while holding `state_commit_lock`, after the final lane
/// retirement veto and before any lane geometry or WSV storage is published.
pub(crate) trait StateBlockCommitAuthorization {
    /// Consume and validate this authorization against State's exact commit
    /// identity.
    fn consume_for_state_commit(
        self: Box<Self>,
        carrier_block_hash: HashOf<BlockHeader>,
        staged_merge_entry: Option<&MergeLedgerEntry>,
    ) -> Result<(), String>;
}
