    fn apply_due_privacy_consensus_policy(&mut self) {
        let incoming_height = self._curr_block.height().get();
        let policy = *self.world.privacy_consensus_policy.get();
        policy.validate().unwrap_or_else(|error| {
            panic!(
                "persisted privacy consensus policy is invalid at incoming block height \
                 {incoming_height}: {error}"
            )
        });
        let Some(pending) = policy.pending_tightening else {
            return;
        };
        if pending.effective_at_height < incoming_height {
            panic!(
                "privacy consensus policy missed effective height {} before incoming block \
                 height {incoming_height}",
                pending.effective_at_height
            );
        }
        if pending.effective_at_height > incoming_height {
            return;
        }
        crate::privacy_state::validate_unanchored_privacy_root_retention_v1(
            &self.world.privacy_roots,
            pending.next_limits.retained_root_count,
        )
        .unwrap_or_else(|error| {
            panic!(
                "scheduled privacy retention tightening is invalid at incoming block height \
                 {incoming_height}: {error}"
            )
        });
        let mut plans = Vec::new();
        for protocol_id in crate::privacy_state::PRIVACY_ROOT_RETENTION_ANCHORED_PROTOCOLS_V1 {
            plans.extend(
                crate::privacy_state::plan_privacy_root_retention_reduction_v1(
                    &self.world.privacy_roots,
                    protocol_id,
                    pending.next_limits.retained_root_count,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "scheduled typed privacy retention tightening for {protocol_id:?} failed at \
                         incoming block height {incoming_height}: {error}"
                    )
                }),
            );
        }
        plans.sort_unstable_by_key(|plan| plan.head_key);
        let mut head_updates = Vec::with_capacity(plans.len());
        for plan in &plans {
            let head = self
                .world
                .privacy_root_heads
                .get(&plan.head_key)
                .copied()
                .unwrap_or_else(|| {
                    panic!(
                        "typed privacy retention plan for {:?}/{:?} has no head at incoming block \
                         height {incoming_height}",
                        plan.head_key.namespace(),
                        plan.head_key.role(),
                    )
                });
            let next_head = crate::privacy_state::PrivacyRootHeadRecordV1::new(
                head.epoch(),
                head.root(),
                head.provenance(),
                Some(plan.new_anchor),
            )
            .unwrap_or_else(|error| {
                panic!(
                    "typed privacy retention anchor for {:?}/{:?} is invalid at incoming block \
                     height {incoming_height}: {error}",
                    plan.head_key.namespace(),
                    plan.head_key.role(),
                )
            });
            head_updates.push((plan.head_key, next_head));
        }
        for plan in plans {
            for key in plan.removal_keys {
                self.world.privacy_roots.remove(key);
            }
        }
        for (key, head) in head_updates {
            self.world.privacy_root_heads.insert(key, head);
        }
        *self.world.privacy_consensus_policy.get_mut() =
            iroha_data_model::privacy::PrivacyConsensusPolicyV1 {
                current_limits: pending.next_limits,
                pending_tightening: None,
            };
        self.privacy_budget_in_block =
            crate::privacy::PrivacyBlockBudgetV1::new(pending.next_limits)
                .expect("validated scheduled privacy limits construct a block budget");
    }
    fn promote_due_privacy_activations(&mut self) {
        let incoming_height = self._curr_block.height().get();
        let promotions = crate::privacy_state::plan_due_privacy_activation_promotions_v1(
            &self.world.privacy_activations,
            incoming_height,
        )
        .unwrap_or_else(|error| {
            panic!(
                "persisted privacy activation registry is invalid at block height \
                     {incoming_height}: {error}"
            )
        });
        for (key, record) in promotions {
            self.world.privacy_activations.insert(key, record);
        }
    }
    fn activate_due_public_lane_validators(&mut self, current_epoch: u64) {
        let block_height = self._curr_block.height().get();
        let pending: Vec<_> = self
            .world
            .public_lane_validators
            .iter()
            .filter_map(|(key, record)| {
                if !public_lane_validator_record_matches_key(key, record) {
                    return None;
                }
                if let PublicLaneValidatorStatus::PendingActivation(target_epoch) = record.status {
                    if target_epoch <= current_epoch {
                        return Some((key.clone(), record.status.clone()));
                    }
                }
                None
            })
            .collect();
        for (key, previous_status) in pending {
            if nexus_staking_authority_lane_at_height(key.0, &self.nexus, block_height)
                != Some(key.0)
            {
                iroha_logger::error!(
                    lane_id = %key.0,
                    validator = %key.1,
                    current_epoch,
                    block_height,
                    "pending validator belongs to a non-owner staking lane; skipping activation"
                );
                continue;
            }
            let Some(mut record) = self.world.public_lane_validators.get(&key).cloned() else {
                continue;
            };
            let telemetry = {
                #[cfg(feature = "telemetry")]
                {
                    Some(self.telemetry)
                }
                #[cfg(not(feature = "telemetry"))]
                {
                    None
                }
            };
            if let Err(err) = crate::smartcontracts::isi::staking::promote_pending_validator(
                &mut record,
                key.0,
                block_height,
                current_epoch,
                &previous_status,
                telemetry,
            ) {
                iroha_logger::error!(
                    lane_id = %key.0,
                    validator = %key.1,
                    current_epoch,
                    block_height,
                    ?err,
                    "pending validator activation failed; skipping"
                );
                continue;
            }
            self.world.public_lane_validators.insert(key, record);
        }
    }
    fn clear_expired_vrf_public_lane_jails(&mut self, current_epoch: u64) {
        let block_height = self._curr_block.height().get();
        let to_restore: Vec<_> = self
            .world
            .public_lane_validators
            .iter()
            .filter_map(|(key, record)| {
                if !public_lane_validator_record_matches_key(key, record) {
                    return None;
                }
                let PublicLaneValidatorStatus::Jailed(reason) = &record.status else {
                    return None;
                };
                let penalty_epoch = vrf_penalty_jail_epoch(reason)?;
                (penalty_epoch < current_epoch).then(|| (key.clone(), record.status.clone()))
            })
            .collect();
        for (key, previous_status) in to_restore {
            if nexus_staking_authority_lane_at_height(key.0, &self.nexus, block_height)
                != Some(key.0)
            {
                iroha_logger::error!(
                    lane_id = %key.0,
                    validator = %key.1,
                    current_epoch,
                    block_height,
                    "jailed validator belongs to a non-owner staking lane; skipping restoration"
                );
                continue;
            }
            let Some(mut record) = self.world.public_lane_validators.get(&key).cloned() else {
                continue;
            };
            record.status = PublicLaneValidatorStatus::Active;
            #[cfg(feature = "telemetry")]
            self.telemetry.record_public_lane_validator_status(
                key.0,
                Some(&previous_status),
                &record.status,
            );
            #[cfg(not(feature = "telemetry"))]
            let _ = previous_status;
            self.world.public_lane_validators.insert(key, record);
        }
    }
    fn record_replayed_axt_envelope(&mut self, envelope: &AxtEnvelopeRecord, current_slot: u64) {
        // The permanent per-dataspace ratchet is independent of the replaceable
        // policy projection. Exact replay keys make both the counter advance
        // and cumulative charge idempotent when a snapshot already contains
        // this exact committed use.
        let mut counter_updates = BTreeMap::<DataSpaceId, AxtHandleCounterRecord>::new();
        let mut budget_updates = BTreeMap::<AxtHandleBudgetKey, AxtHandleBudgetRecord>::new();
        let mut replay_records = Vec::with_capacity(envelope.handles.len());
        for handle in &envelope.handles {
            let retain_until_slot = retain_until_slot_for_handle(handle, &self.nexus, current_slot);
            let replay_key =
                AxtHandleReplayKey::from_handle(handle.intent.asset_dsid, &handle.handle);
            let budget_key = AxtHandleBudgetKey::from_handle(&handle.handle);
            if let Some(replay_record) = self.world.axt_replay_ledger.get(&replay_key) {
                assert_eq!(
                    replay_record.budget_key, budget_key,
                    "persisted AXT replay key must reference the exact consumed budget family"
                );
                replay_record
                    .validate_for_key(&replay_key)
                    .expect("persisted AXT replay record must remain canonical");
                let counter = counter_updates
                    .get(&handle.intent.asset_dsid)
                    .copied()
                    .or_else(|| {
                        self.world
                            .axt_handle_counters
                            .get(&handle.intent.asset_dsid)
                            .copied()
                    })
                    .expect("persisted AXT replay key must retain its permanent counter ratchet");
                assert!(
                    counter.next() > handle.handle.sub_nonce,
                    "persisted AXT replay key must have an already-advanced counter ratchet"
                );
                self.world
                    .axt_handle_budget_ledger
                    .get(&replay_record.budget_key)
                    .expect(
                        "persisted AXT replay key must retain its cumulative family budget record",
                    )
                    .validate_for_key(&replay_record.budget_key)
                    .expect("persisted AXT replay budget evidence must remain canonical");
            } else {
                let counter = counter_updates
                    .entry(handle.intent.asset_dsid)
                    .or_insert_with(|| {
                        self.world
                            .axt_handle_counters
                            .get(&handle.intent.asset_dsid)
                            .copied()
                            .unwrap_or_else(|| {
                                AxtHandleCounterRecord::initial(handle.handle.handle_era)
                            })
                    });
                counter
                    .try_advance(handle.handle.handle_era, handle.handle.sub_nonce)
                    .expect("committed AXT replay must advance the permanent dataspace counter");
                assert_eq!(
                    budget_key.asset_dsid(),
                    handle.intent.asset_dsid,
                    "committed AXT replay handle budget key must match its intent dataspace"
                );
                let amount = resolve_axt_handle_budget_amount(envelope, handle)
                    .expect("committed AXT replay amount must resolve from its selected proof");
                let budget_record = budget_updates.entry(budget_key.clone()).or_insert_with(|| {
                    self.world
                        .axt_handle_budget_ledger
                        .get(&budget_key)
                        .cloned()
                        .unwrap_or_else(AxtHandleBudgetRecord::empty)
                });
                budget_record
                    .try_consume(&budget_key, &amount, retain_until_slot)
                    .expect("committed AXT replay must remain within its signed family budget");
                replay_records.push((
                    replay_key,
                    handle.intent.asset_dsid,
                    budget_key,
                    retain_until_slot,
                ));
            }
        }
        for (dataspace, counter) in counter_updates {
            self.world.axt_handle_counters.insert(dataspace, counter);
            if let Some(mut policy) = self.world.axt_policies.get(&dataspace).copied() {
                policy.next_handle_counter = counter.next();
                policy.active_handle_era = counter.authorization_generation();
                self.world.axt_policies.insert(dataspace, policy);
            }
        }
        for (key, record) in budget_updates {
            self.world.axt_handle_budget_ledger.insert(key, record);
        }
        for (key, dataspace, budget_key, retain_until_slot) in replay_records {
            self.world.axt_replay_ledger.insert(
                key,
                AxtReplayRecord {
                    dataspace,
                    budget_key,
                    used_slot: current_slot,
                    retain_until_slot,
                },
            );
        }
    }
