    /// Derive a snapshot of AXT policies (per dataspace).
    fn axt_policy_snapshot(&self) -> AxtPolicySnapshot {
        let mut entries: Vec<AxtPolicyBinding> = self
            .axt_policies()
            .iter()
            .map(|(dsid, policy)| AxtPolicyBinding {
                dsid: *dsid,
                policy: *policy,
            })
            .collect();
        entries.sort_by_key(|binding| binding.dsid);
        let version = AxtPolicySnapshot::compute_version(&entries);
        let mut snapshot = AxtPolicySnapshot { version, entries };
        project_axt_handle_counters(self, &mut snapshot);
        snapshot
    }
