    // Account-related methods
    /// Get `Account` and return reference to it.
    ///
    /// # Errors
    /// Fails if there is no domain or account
    fn account<'a>(&'a self, id: &'a AccountId) -> Result<AccountEntry<'a>, FindError> {
        self.accounts()
            .get(id)
            .map(|value| AccountEntry::new(id, value))
            .ok_or_else(|| FindError::Account(id.clone()))
    }
    /// Get `Account` and pass it to closure.
    ///
    /// # Errors
    /// Fails if there is no domain or account
    fn map_account<T>(
        &self,
        id: &AccountId,
        f: impl FnOnce(AccountEntry) -> T,
    ) -> Result<T, QueryExecutionFail> {
        let account = self.account(id)?;
        Ok(f(account))
    }
    /// Resolve one dataspace binding for a concrete account when a UAID-backed
    /// Space Directory entry exists.
    ///
    /// Prefer [`WorldReadOnly::account_scope_hierarchy`] when the caller needs the full
    /// `1..many` dataspace and `0..many` domain view for the account.
    fn dataspace_for_account(&self, account_id: &AccountId) -> Option<DataSpaceId> {
        let account = self.account(account_id).ok()?;
        let uaid = account.value().uaid().copied()?;
        self.uaid_dataspaces()
            .get(&uaid)
            .and_then(|bindings| bindings.dataspace_for_account(account_id))
    }
    /// Get [`Account`]'s [`RoleId`]s
    // NOTE: have to use concreate type because don't want to capture lifetme of `id`
    #[allow(clippy::type_complexity)]
    fn account_roles_iter<'slf>(
        &'slf self,
        id: &AccountId,
    ) -> core::iter::Map<
        RangeIter<'slf, RoleIdWithOwner, ()>,
        fn((&'slf RoleIdWithOwner, &'slf ())) -> &'slf RoleId,
    > {
        self.account_roles()
            .range(RoleIdByAccountBounds::new(id))
            .map(|(role, ())| &role.id)
    }
