    fn da_shard_cursor_journal_path(&self) -> PathBuf {
        let root = self.kura.store_root();
        if root.as_os_str().is_empty() {
            return PathBuf::new();
        }
        DaShardCursorJournal::journal_path(&root)
    }
    fn persist_da_shard_cursor_journal(&self) {
        let path = self.da_shard_cursor_journal_path();
        if path.as_os_str().is_empty() {
            return;
        }
        let lane_config = self.nexus_snapshot().lane_config.clone();
        let snapshot = {
            let cursors = self.da_shard_cursors.read().clone();
            DaShardCursorJournal::from_index(&lane_config, &cursors, &path)
        };
        if let Err(err) = snapshot.persist() {
            warn!(
                ?err,
                path = %path.display(),
                "failed to persist DA shard cursor journal"
            );
        }
    }
    fn schedule_da_shard_cursor_journal_persist(&self) {
        let path = self.da_shard_cursor_journal_path();
        if path.as_os_str().is_empty() {
            return;
        }
        let lane_config = self.nexus_snapshot().lane_config.clone();
        let snapshot = {
            let cursors = self.da_shard_cursors.read().clone();
            DaShardCursorJournal::from_index(&lane_config, &cursors, &path)
        };
        self.da_shard_cursor_persistor.schedule(snapshot);
    }
    fn journal_reset_heights_at_or_below(
        journal: &DaShardCursorJournal,
        latest_height: u64,
    ) -> BTreeMap<LaneId, u64> {
        journal
            .canonical_reset_heights()
            .iter()
            .filter_map(|(lane_id, reset_height)| {
                if *reset_height <= latest_height {
                    Some((*lane_id, *reset_height))
                } else {
                    warn!(
                        lane = %lane_id.as_u32(),
                        reset_height,
                        latest_height,
                        "ignoring persisted lane reset watermark ahead of canonical replay height"
                    );
                    None
                }
            })
            .collect()
    }
    fn restore_da_cursors_from_journal(
        &self,
        cursors: &mut DaShardCursorIndex,
        lane_config: &iroha_config::parameters::actual::LaneConfig,
        journal: &DaShardCursorJournal,
        latest_height: u64,
    ) -> Result<usize, DaShardCursorError> {
        let mut restored = 0_usize;
        cursors.merge_canonical_reset_heights(&Self::journal_reset_heights_at_or_below(
            journal,
            latest_height,
        ));
        for entry in journal.entries() {
            if entry.last_block_height > latest_height {
                warn!(
                    lane = %entry.lane_id.as_u32(),
                    shard = %entry.shard_id.as_u32(),
                    cursor_height = entry.last_block_height,
                    latest_height,
                    "skipping persisted DA shard cursor ahead of latest block height"
                );
                continue;
            }
            if cursors.restore_from_journal_entry(lane_config, entry)? {
                restored = restored.saturating_add(1);
                #[cfg(feature = "telemetry")]
                self.telemetry.record_da_shard_cursor_event(
                    "journal_restore",
                    entry.lane_id.as_u32(),
                    entry.shard_id.as_u32(),
                    entry.last_block_height,
                );
            }
        }
        Ok(restored)
    }
