    /// _(test only)_ Create state with mock telemetry (depends on features)
    #[must_use]
    #[inline]
    #[cfg(test)]
    fn test_da_spool_override() -> Option<std::path::PathBuf> {
        std::env::var_os("IROHA_DA_SPOOL_DIR").map(std::path::PathBuf::from)
    }
    /// _(test only)_ Create state with mock telemetry (depends on features)
    #[must_use]
    #[inline]
    #[cfg(test)]
    pub fn new(world: World, kura: Arc<Kura>, query_handle: LiveQueryStoreHandle) -> Self {
        let mut s = Self::try_new(
            world,
            kura,
            query_handle,
            #[cfg(feature = "telemetry")]
            <_>::default(),
        )
        .expect("test fixture durable State startup journals must validate");
        if let Some(spool_path) = Self::test_da_spool_override() {
            match crate::da::commitments::load_commitment_store(&spool_path) {
                Ok(store) => s.da_commitments = parking_lot::RwLock::new(store),
                Err(err) => {
                    iroha_logger::warn!(
                        spool_path = %spool_path.display(),
                        ?err,
                        "Failed to pre-load DA commitments; continuing with empty store"
                    )
                }
            }
            match crate::da::pin_intents::load_pin_intents(&spool_path) {
                Ok(Some(intents)) => {
                    let _ = s.ingest_pin_intents(0, intents, "test-spool-preload");
                }
                Ok(None) => {}
                Err(err) => {
                    iroha_logger::warn!(
                        spool_path = %spool_path.display(),
                        ?err,
                        "Failed to pre-load DA pin intents; continuing with empty store"
                    )
                }
            }
        }
        s.install_active_lane_markers_for_tests();
        s.gov.citizenship_bond_amount = Quantity::zero();
        s.disable_nexus_fees_for_testing();
        s
    }
